  function stringifyArg (arg) {
    if (typeof arg === 'function') {
      return 'function(){}'
    } else if (Array.isArray(arg)) {
      return `[${arg.map(stringifyArg).join(', ')}]`
    } else if (typeof arg === 'object') {
      return `{${Object.keys(arg)
        .map(key => `${key}: ${stringifyArg(arg[key])}`)
        .join(', ')}}`
